def _replay_ros_payload(request: PlaybackControlRequest) -> dict[str, Any]:
    params = request.params or {}
    command = request.command
    payload: dict[str, Any] = {"type": command}

    if command == "load":
        bag_path = params.get("path") or params.get("bag_path")
        if not bag_path:
            raise HTTPException(status_code=400, detail="load requires params.path")
        payload["bag_path"] = bag_path
    elif command == "seek":
        payload["timestamp"] = params.get("time", params.get("timestamp", 0.0))
    elif command == "set_rate":
        payload["rate"] = params.get("rate", 1.0)
    elif command not in {"play", "pause", "stop"}:
        raise HTTPException(status_code=400, detail=f"Unsupported replay command: {command}")

    return payload


service_manager = ServiceManager()
ros_runtime = RosStateRuntime()
state_node: ApexStateNode | None = None
topic_bridge: TopicBridge | None = None
footkey_publisher: Any | None = None
footkey_publisher_node: ApexStateNode | None = None
