STAND_OPTIONS = ("legacy", "new", "m6stand", "m6litestand", "user")
ARM_AXIS_OFFSETS_M = {
    "m6s_696": 0.1745,
    "m3s_615": 0.1586,
    "m6s_lite_615": 0.1586,
    "m6s_lite_680": 0.1586,
    "m6s_lite_750": 0.1586,
    "m6s_809": 0.1745,
}


@asynccontextmanager
async def lifespan(_: FastAPI):
    global state_node, topic_bridge
    state_node = ros_runtime.start()
    topic_bridge = TopicBridge(state_node)
    try:
        yield
    finally:
        if topic_bridge is not None:
            topic_bridge.stop()
            topic_bridge = None
        ros_runtime.stop()


app = FastAPI(
    title="Apex Unified Backend",
    version="0.1.0",
    description="REST and WebSocket entrypoint for Apex module management.",
    lifespan=lifespan,
)
app.add_middleware(
    CORSMiddleware,
    allow_origins=["*"],
    allow_credentials=True,
    allow_methods=["*"],
    allow_headers=["*"],
)


@app.post("/api/v1/backend_connect")
def backend_connect(request: BackendConnectRequest | None = None) -> dict[str, Any]:
    robot = _robot_snapshot()
    for key in ("source", "config_file", "configured", "robot_info_received"):
        robot.pop(key, None)
    return ok(
        {
            "connected": True,
            "backend": {
                "name": "apex_backend",
                "api_version": "v1",
                "server_time_sec": time.time(),
            },
            "robot": robot,
        }
    )


