@app.websocket("/ws/v1/modules")
async def module_status_ws(websocket: WebSocket) -> None:
    await websocket.accept()
    try:
        while True:
            await websocket.send_json({"type": "module_status", "data": service_manager.list_modules()})
            await asyncio.sleep(1.0)
    except WebSocketDisconnect:
        return


@app.websocket("/ws/v1/logs/{module_id}")
async def module_logs_ws(websocket: WebSocket, module_id: str) -> None:
    await websocket.accept()
    try:
        config = service_manager.get_config(module_id)
    except KeyError as exc:
        await websocket.send_json({"type": "error", "message": str(exc)})
        await websocket.close(code=1008)
        return

    try:
        if getattr(service_manager, "host_control_enabled", False):
            async for line in service_manager.follow_logs(module_id, lines=50):
                await websocket.send_json(
                    {
                        "type": "log",
                        "module": module_id,
                        "service": config.service,
                        "line": line,
                    }
                )
            return
        command = [
            "journalctl",
            "-fu",
            config.service,
            "-n",
            "50",
            "--no-pager",
            "-o",
            "short-iso",
        ]
        if os.geteuid() != 0:
            command = ["sudo", "-n", *command]
        process = await asyncio.create_subprocess_exec(
            *command,
            stdout=asyncio.subprocess.PIPE,
            stderr=asyncio.subprocess.PIPE,
        )
    except (OSError, ServiceManagerError) as exc:
        await websocket.send_json({"type": "error", "message": str(exc)})
        await websocket.close(code=1011)
        return
    try:
        assert process.stdout is not None
        while True:
            line = await process.stdout.readline()
            if not line:
                break
            await websocket.send_json(
                {
                    "type": "log",
                    "module": module_id,
                    "service": config.service,
                    "line": line.decode("utf-8", errors="replace").rstrip(),
                }
            )
    except WebSocketDisconnect:
        return
    finally:
        if process.returncode is None:
            process.terminate()
            try:
                await asyncio.wait_for(process.wait(), timeout=2.0)
            except asyncio.TimeoutError:
                process.kill()


@app.websocket("/ws/v1/events")
async def events_ws(websocket: WebSocket) -> None:
    await websocket.accept()
    last_payload = ""
    try:
        while True:
            payload = {
                "modules": service_manager.list_modules(),
                "control": _state().snapshot(),
            }
            encoded = json.dumps(payload, sort_keys=True, default=str)
            if encoded != last_payload:
                await websocket.send_json({"type": "system_event", "data": payload})
                last_payload = encoded
            await asyncio.sleep(1.0)
    except WebSocketDisconnect:
        return


@app.websocket("/ws/v1/topics")
async def topics_ws(websocket: WebSocket) -> None:
    await websocket.accept()
    client = _topic_bridge().add_client()
    sender = asyncio.create_task(_send_topic_messages(websocket, client))
    receiver = asyncio.create_task(_drain_topic_client_messages(websocket))
    try:
        done, pending = await asyncio.wait({sender, receiver}, return_when=asyncio.FIRST_COMPLETED)
        for task in pending:
            task.cancel()
        for task in done:
            task.result()
    except WebSocketDisconnect:
        return
    finally:
        _topic_bridge().remove_client(client)


@app.websocket("/ws/v1/teleop/control")
async def teleop_control_ws(websocket: WebSocket) -> None:
    await websocket.accept()
    try:
        while True:
            payload = await websocket.receive_json()
            if not isinstance(payload, dict):
                await websocket.send_json({"type": "error", "message": "Unsupported teleop control message"})
                continue

            if payload.get("type") == "teleop_motion_mode":
                try:
                    mode_value = _teleop_motion_mode_value(payload.get("mode"))
                    result = await asyncio.to_thread(_state().set_teleop_motion_mode, mode_value)
                except HTTPException as exc:
                    await websocket.send_json({"type": "error", "message": exc.detail})
                    continue
                if not result.get("success"):
                    await websocket.send_json(
                        {"type": "error", "message": result.get("error", "Teleop mode switch failed")}
                    )
                    continue
                await websocket.send_json({"type": "teleop_motion_mode", **result})
                continue

            if payload.get("type") == "ik_input":
                input_id = payload.get("input")
                if not isinstance(input_id, int) or isinstance(input_id, bool):
                    await websocket.send_json(
                        {"type": "error", "message": "ik_input.input must be 0, 1, 2, or 3"}
                    )
                    continue
                try:
                    result = await asyncio.to_thread(_state().set_ik_input, input_id)
                except (RuntimeError, TimeoutError) as exc:
                    await websocket.send_json({"type": "error", "message": str(exc)})
                    continue
                if not result.get("success"):
                    await websocket.send_json(
                        {
                            "type": "error",
                            "message": result.get("error", "IK input switch failed"),
                        }
                    )
                    continue
                await websocket.send_json({"type": "ik_input", **result})
                continue

            if payload.get("type") != "footkey":
                await websocket.send_json({"type": "error", "message": "Unsupported teleop control message"})
                continue

            pressed = payload.get("pressed")
            if not isinstance(pressed, bool):
                await websocket.send_json({"type": "error", "message": "footkey.pressed must be boolean"})
                continue

            _publish_footkey(pressed)
            await websocket.send_json({"type": "footkey", "pressed": pressed})
    except WebSocketDisconnect:
        return
    finally:
        _publish_footkey(False)


def ok(data: Any) -> dict[str, Any]:
    return {"ok": True, "data": data}


def _state() -> ApexStateNode:
    if state_node is None:
        raise HTTPException(status_code=503, detail="ROS state node is not ready")
    return state_node


def _topic_bridge() -> TopicBridge:
    if topic_bridge is None:
        raise HTTPException(status_code=503, detail="Topic bridge is not ready")
    return topic_bridge


def _publish_footkey(pressed: bool) -> None:
    from std_msgs.msg import Bool

    _footkey_publisher().publish(Bool(data=pressed))


def _footkey_publisher() -> Any:
    global footkey_publisher, footkey_publisher_node

    node = _state()
    if footkey_publisher is None or footkey_publisher_node is not node:
        from std_msgs.msg import Bool

        footkey_publisher = node.create_publisher(Bool, "control/footkey", 10)
        footkey_publisher_node = node
    return footkey_publisher


def _robot_info_snapshot() -> dict[str, Any]:
    state = _state()
    snapshot = getattr(state, "robot_info_snapshot", None)
    if callable(snapshot):
        return snapshot()
    if topic_bridge is not None:
        return topic_bridge.robot_info_snapshot()
    return {
        "robot_type": "unknown",
        "controller_version": None,
        "controller_version_text": "unknown",
        "stamp_ns": None,
        "age_sec": None,
        "received": False,
    }


def _robot_snapshot() -> dict[str, Any]:
    robot_info = _robot_info_snapshot()
    robot_config = _robot_config_snapshot()
    if not robot_config["configured"]:
        robot_info["source"] = "robot_info" if robot_info.get("received") else "unknown"
        robot_info["robot_info_received"] = bool(robot_info.get("received"))
        return robot_info

    robot = dict(robot_info)
    robot.update(robot_config)
    robot["received"] = True
    robot["robot_info_received"] = bool(robot_info.get("received"))
    return robot


def _robot_config_snapshot() -> dict[str, Any]:
    config = _apex_env_values()
    robot_platform = config.get("APEX_ROBOT_PLATFORM", "").strip().lower()
    compute_platform = config.get("APEX_COMPUTE_PLATFORM", "").strip().lower()
    robot_model = _normalize_robot_model(config.get("APEX_ROBOT_MODEL", "").strip())
    base_model, arm_model = _split_robot_model(robot_model)
    stand_shoulder_width_m, stand_height_m = _configured_stand_dimensions(
        base_model, arm_model, config
    )
    tool_type = config.get("APEX_TOOL_TYPE", "").strip().lower() or "dm"
    teleop_mode = config.get("APEX_TELEOP_MODE", "").strip().lower() or "controller"

    return {
        "robot_type": robot_model or "unknown",
        "robot_platform": robot_platform or "unknown",
        "compute_platform": compute_platform or None,
        "robot_model": robot_model or "unknown",
        "base_model": base_model,
        "arm_model": arm_model,
        "stand_shoulder_width_m": stand_shoulder_width_m,
        "stand_height_m": stand_height_m,
        "stand_options": list(STAND_OPTIONS),
        "tool_type": tool_type,
        "teleop_mode": teleop_mode,
        "source": "config" if robot_platform or robot_model else "unknown",
        "config_file": _apex_env_file(),
        "configured": bool(robot_platform or robot_model),
    }


def _apex_env_values() -> dict[str, str]:
    values = _read_env_file(_apex_env_file())
    for key in (
        "APEX_ROBOT_PLATFORM",
        "APEX_COMPUTE_PLATFORM",
        "APEX_ROBOT_MODEL",
        "APEX_STAND_SHOULDER_WIDTH_M",
        "APEX_STAND_HEIGHT_M",
        "APEX_TOOL_TYPE",
        "APEX_TELEOP_MODE",
    ):
        if key not in values and key in os.environ:
            values[key] = os.environ[key]
    return values


def _apex_env_file() -> str:
    return os.environ.get("APEX_ENV_FILE", APEX_ENV_FILE)


def _read_env_file(path: str) -> dict[str, str]:
    values: dict[str, str] = {}
    try:
        with open(path, encoding="utf-8") as env_file:
            for raw_line in env_file:
                line = raw_line.strip()
                if not line or line.startswith("#") or "=" not in line:
                    continue
                key, value = line.split("=", 1)
                values[key.strip()] = _strip_env_value(value.strip())
    except FileNotFoundError:
        pass
    return values


def _strip_env_value(value: str) -> str:
    if len(value) >= 2 and value[0] == value[-1] and value[0] in {"'", '"'}:
        return value[1:-1]
    return value


def _normalize_robot_model(robot_model: str) -> str:
    normalized = robot_model.lower()
    aliases = {
        "sky": "skye",
        "lunav3": "luna_v3",
        "skyev2": "skye_v2_920",
        "skye_v2": "skye_v2_920",
        "skye920": "skye_v2_920",
        "gento_skye_v2": "skye_v2_920",
        "gento_skye_v2_920": "skye_v2_920",
    }
    return aliases.get(normalized, normalized)


def _split_robot_model(robot_model: str) -> tuple[str | None, str | None]:
    parts = robot_model.split("_")
    if len(parts) < 4 or parts[0] != "pro":
        return None, None
    base_model = parts[-1]
    arm_model = "_".join(parts[1:-1])
    return base_model or None, arm_model or None


def _optional_positive_float(value: str | None) -> float | None:
    try:
        result = float(value or "")
    except (TypeError, ValueError):
        return None
    return result if math.isfinite(result) and result > 0.0 else None


def _configured_stand_dimensions(
    base_model: str | None,
    arm_model: str | None,
    config: dict[str, str],
) -> tuple[float | None, float | None]:
    if base_model == "m6stand":
        return 0.443, 1.121
    if base_model == "m6litestand":
        return 0.4112, 1.121
    if base_model == "user":
        return (
            _optional_positive_float(config.get("APEX_STAND_SHOULDER_WIDTH_M")),
            _optional_positive_float(config.get("APEX_STAND_HEIGHT_M")),
        )
    axis_offset = ARM_AXIS_OFFSETS_M.get(arm_model or "")
    if base_model in {"legacy", "new"} and axis_offset is not None:
        return 2.0 * (0.026 + axis_offset), 1.121
    return None, None


def _module_status(module_id: str) -> dict[str, Any]:
    try:
        status = service_manager.get_status(module_id)
    except KeyError as exc:
        raise HTTPException(status_code=404, detail=str(exc)) from exc
    if module_id == "robot":
        status["control"] = _state().snapshot()
    return status


def _module_action(action: str, handler: Any, module_id: str) -> dict[str, Any]:
    status = _service_action(handler, module_id)
    return {
        "action": action,
        "module": module_id,
        "service": status["service"],
        "status": status,
    }


def _validate_teleop_start(module_id: str) -> None:
    if module_id != "teleop":
        return
    robot_status = _module_status("robot")
    allowed, reason = _state().require_robot_service_active(robot_status)
    if not allowed:
        raise HTTPException(
            status_code=409,
            detail={
                "message": "Teleop start rejected",
                "reason": reason,
                "robot": robot_status,
                "control": _state().snapshot(),
            },
        )


def _service_action(action: Any, *args: Any) -> Any:
    try:
        return action(*args)
    except KeyError as exc:
        raise HTTPException(status_code=404, detail=str(exc)) from exc
    except ServiceManagerError as exc:
        raise HTTPException(status_code=500, detail=str(exc)) from exc


def _robot_action(action: Any) -> Any:
    try:
        return action()
    except (RuntimeError, TimeoutError) as exc:
        raise HTTPException(status_code=503, detail=str(exc)) from exc


def _teleop_motion_mode_value(mode: Any) -> int:
    # Names and values come from the single mapping in ros_state so the REST /
    # WebSocket surface and the ROS service cannot drift apart when a motion
    # scope is added.
    values = {name: value for value, name in TELEOP_MOTION_MODE_NAMES.items()}
    if not isinstance(mode, str) or mode not in values:
        supported = ", ".join(f"'{name}'" for name in sorted(values, key=values.get))
        raise HTTPException(status_code=400, detail=f"mode must be one of {supported}")
    return values[mode]


@app.post("/api/v1/control/teleop_motion_mode")
def set_teleop_motion_mode_v1(request: TeleopMotionModeRequest) -> dict[str, Any]:
    mode_value = _teleop_motion_mode_value(request.mode)
    result = _robot_action(lambda: _state().set_teleop_motion_mode(mode_value))
    if not result.get("success"):
        raise HTTPException(status_code=503, detail=result.get("error", "Teleop mode switch failed"))
    return ok(result)


@app.get("/api/v1/control/base_mode")
def get_base_mode_v1() -> dict[str, Any]:
    snapshot = _state().snapshot()
    return ok({"mode": snapshot["base_mode"], "mode_name": snapshot["base_mode_name"]})


@app.post("/api/v1/control/base_mode")
def set_base_mode_v1(request: BaseModeRequest) -> dict[str, Any]:
    if request.mode not in (0, 1, 2):
        raise HTTPException(
            status_code=400,
            detail="mode must be 0=no_base, 1=joystick, or 2=whole_body",
        )
    result = _robot_action(lambda: _state().set_base_mode(request.mode))
    if not result.get("success"):
        raise HTTPException(status_code=503, detail=result.get("error", "Base mode switch failed"))
    return ok(result)


def _recorder_command(command: dict[str, Any]) -> dict[str, Any]:
    try:
        result = _state().recorder_control(command)
    except (RuntimeError, TimeoutError) as exc:
        raise HTTPException(status_code=503, detail=str(exc)) from exc
    if result.get("status") == "error":
        raise HTTPException(status_code=503, detail=result.get("error_message", "Recorder control failed"))
    return result


def _legacy_result(action: Any) -> dict[str, Any]:
    try:
        result = action()
        return {"status": "success", "result": result}
    except Exception as exc:
        return {"status": "error", "message": str(exc)}
    
@app.post("/api/v1/control/set_input")
def set_robot_input_v1(request: InputRequest) -> dict[str, Any]:
    return ok(_robot_action(lambda: _state().set_input(request.input)))

@app.post("/api/v1/control/set_ik_input")
def set_robot_ik_input_v1(request: InputRequest) -> dict[str, Any]:
    result = _robot_action(lambda: _state().set_ik_input(request.input))
    if not result.get("success"):
        raise HTTPException(
            status_code=400,
            detail=result.get("error", "IK input switch failed"),
        )
    return ok(result)

if _apex_env_values().get("APEX_ROBOT_PLATFORM", "").strip().lower() == "pro":

    @app.get("/api/v1/replay/status")
    def replay_status_v1() -> dict[str, Any]:
        return ok(_state().get_playback_status())

    @app.post("/api/v1/replay/control")
    def replay_control_v1(request: PlaybackControlRequest) -> dict[str, Any]:
        payload = _replay_ros_payload(request)
        try:
            result = _state().playback_control(payload)
        except (RuntimeError, TimeoutError) as exc:
            raise HTTPException(status_code=503, detail=str(exc)) from exc
        if result.get("status") == "error":
            raise HTTPException(status_code=503, detail=result.get("error_message", "Playback control failed"))
        return ok({"command": request.command, "result": result})

    @app.get("/api/v1/replay/bags")
    def replay_bags_v1() -> dict[str, Any]:
        return ok(_state().get_bag_files())

    @app.get("/api/v1/replay/bags/info")
    def replay_bag_info_v1(
        path: str = Query(..., description="Absolute path to the bag directory"),
        fast_mode: bool = Query(default=True),
    ) -> dict[str, Any]:
        info = _state().get_bag_info(path, fast_mode=fast_mode)
        if info is None:
            raise HTTPException(status_code=404, detail=f"Bag not found or unreadable: {path}")
        return ok(info)

    @app.post("/api/v1/record/start")
    def record_start_v1(request: RecordStartRequest | None = None) -> dict[str, Any]:
        command: dict[str, Any] = {"action": "start"}
        if request is not None and request.topics is not None:
            command["topics"] = request.topics
        return ok(_recorder_command(command))

    @app.post("/api/v1/record/stop")
    def record_stop_v1() -> dict[str, Any]:
        return ok(_recorder_command({"action": "stop"}))

    @app.get("/api/v1/record/status")
    def record_status_v1() -> dict[str, Any]:
        return ok(_recorder_command({"action": "status"}))

    @app.get("/api/v1/record/topics")
    def record_topics_v1() -> dict[str, Any]:
        return ok(_recorder_command({"action": "get_topics"}))

    @app.get("/api/v1/storage/status")
    def storage_status_v1() -> dict[str, Any]:
        return ok(_recorder_command({"action": "storage_status"}))

    @app.post("/api/v1/storage/clear_error")
    def storage_clear_error_v1() -> dict[str, Any]:
        return ok(_recorder_command({"action": "clear_storage_error"}))


async def _send_topic_messages(websocket: WebSocket, client: TopicBridgeClient) -> None:
    while True:
        await websocket.send_text(await client.queue.get())


async def _drain_topic_client_messages(websocket: WebSocket) -> None:
    while True:
        await websocket.receive_text()


def main() -> None:
    host = os.environ.get("APEX_BACKEND_HOST", "0.0.0.0")
    port = int(os.environ.get("APEX_BACKEND_PORT", "8080"))
    uvicorn.run("apex_backend.backend:app", host=host, port=port, access_log=False)


if __name__ == "__main__":
    main()
